"use client";
import { motion, AnimatePresence } from "framer-motion";
import { useState, useEffect } from "react";

export default function BootSequence({ onComplete }) {
  // We use two paths: one for the bright white laser core, 
  // and a thicker, blurred one underneath for the purple "burn" mark.
  
  const nourPath = "../public/nour.svg"; 

  return (
    <motion.div
      className="fixed inset-0 z-50 flex items-center justify-center bg-[#050505]"
      initial={{ opacity: 1 }}
      animate={{ opacity: 0 }}
      transition={{ delay: 2.8, duration: 0.8, ease: "easeInOut" }}
      onAnimationComplete={onComplete}
    >
      <svg
        viewBox="0 0 800 300" // Adjust this to match your original SVG viewbox
        className="w-full max-w-2xl"
        fill="none"
      >
        {/* Layer 1: The Purple "Burn" Mark (Thick & Blurred) */}
        <motion.path
          d={nourPath}
          stroke="#8b5cf6" // Tailwind purple-500
          strokeWidth="8"
          strokeLinecap="round"
          filter="blur(8px)"
          initial={{ pathLength: 0, opacity: 0 }}
          animate={{ pathLength: 1, opacity: 0.8 }}
          transition={{ 
            pathLength: { duration: 1.5, ease: "easeInOut" },
            opacity: { duration: 0.2 }
          }}
        />

        {/* Layer 2: The Bright Laser Core (Thin & White) */}
        <motion.path
          d={nourPath}
          stroke="#ffffff"
          strokeWidth="2"
          strokeLinecap="round"
          initial={{ pathLength: 0, opacity: 1 }}
          animate={{ pathLength: 1, opacity: 0 }} // Fades out faster than the burn
          transition={{ 
            pathLength: { duration: 1.5, ease: "easeInOut" },
            opacity: { delay: 1.6, duration: 0.4 } // Laser dies, leaving the burn
          }}
        />
      </svg>
    </motion.div>
  );
}